// components/pages/Activation.js
import React, { useState, useEffect } from 'react';
import { apiCall, escapeHtml } from '../../utils/api';

const Activation = ({ showToast }) => {
  const [tills, setTills] = useState([]);
  const [loading, setLoading] = useState(true);

  const loadData = async () => {
    setLoading(true);
    const result = await apiCall('getTills');
    if (result.success) {
      setTills(result.tills || []);
    }
    setLoading(false);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleActivate = async (rowIndex) => {
    const pin = prompt('Enter Start PIN (4-6 digits):');
    if (pin && pin.length >= 4) {
      const res = await apiCall('activateTill', { rowIndex, startPin: pin });
      if (res.success) {
        showToast('Till activated successfully!');
        loadData();
      } else {
        showToast('Activation failed: ' + res.error, true);
      }
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <i className="fas fa-spinner fa-pulse"></i> Loading tills...
      </div>
    );
  }

  if (tills.length === 0) {
    return (
      <div className="empty-state">
        <i className="fas fa-inbox"></i>
        <br />No tills registered yet
      </div>
    );
  }

  return (
    <>
      <h3 className="section-title"><i className="fas fa-toggle-on"></i> Till Activation</h3>
      <div className="table-wrapper">
        <table className="modern-table">
          <thead>
            <tr>
              <th>Name</th>
              <th>Till Number</th>
              <th>Store</th>
              <th>Status</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {tills.map((till, index) => {
              const isActive = till.status === 'active';
              return (
                <tr key={index}>
                  <td><strong>{escapeHtml(till.name || '-')}</strong></td>
                  <td>{escapeHtml(till.tillNumber || '-')}</td>
                  <td>{escapeHtml(till.storeNumber || '-')}</td>
                  <td>
                    {isActive ? 
                      <span className="badge badge-success">Active</span> : 
                      <span className="badge badge-danger">Inactive</span>
                    }
                  </td>
                  <td>
                    {!isActive ? 
                      <button 
                        className="action-btn" 
                        onClick={() => handleActivate(till.rowIndex)}
                      >
                        Activate
                      </button> : 
                      <span className="badge badge-success">Activated</span>
                    }
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </>
  );
};

export default Activation;
